284	fn complete_option(
285	    arg: &clap_lex::ParsedArg<'_>,
286	    cmd: &clap::Command,
287	    current_dir: Option<&std::path::Path>,
288	    disabled: &HashSet<Id>,
289	) -> Vec<CompletionCandidate> {
290	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
291	    let mut completions = Vec::<CompletionCandidate>::new();
292	    if arg.is_empty() {
293	        completions.extend(longs_and_visible_aliases(cmd, disabled));
294	        completions.extend(hidden_longs_aliases(cmd, disabled));
295	
296	        let dash_or_arg = if arg.is_empty() {
297	            "-".into()
298	        } else {
299	            arg.to_value_os().to_string_lossy()
300	        };
301	        completions.extend(
302	            shorts_and_visible_aliases(cmd, disabled)
303	                .into_iter()
304	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
305	        );
306	    } else if arg.is_stdio() {
307	        // HACK: Assuming knowledge of is_stdio
308	        let dash_or_arg = if arg.is_empty() {
309	            "-".into()
310	        } else {
311	            arg.to_value_os().to_string_lossy()
312	        };
313	        completions.extend(
314	            shorts_and_visible_aliases(cmd, disabled)
315	                .into_iter()
316	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
317	        );
318	
319	        completions.extend(longs_and_visible_aliases(cmd, disabled));
320	        completions.extend(hidden_longs_aliases(cmd, disabled));
321	    } else if arg.is_escape() {
322	        // HACK: Assuming knowledge of is_escape
323	        completions.extend(longs_and_visible_aliases(cmd, disabled));
324	        completions.extend(hidden_longs_aliases(cmd, disabled));
325	    } else if let Some((flag, value)) = arg.to_long() {
326	        if let Ok(flag) = flag {
327	            if let Some(value) = value {
328	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
329	                    if !disabled.contains(arg.get_id()) {
330	                        completions.extend(
331	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
332	                                .into_iter()
333	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
334	                        );
335	                    }
336	                }
337	            } else {
338	                completions.extend(
339	                    longs_and_visible_aliases(cmd, disabled)
340	                        .into_iter()
341	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
342	                );
343	                completions.extend(
344	                    hidden_longs_aliases(cmd, disabled)
345	                        .into_iter()
346	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
347	                );
348	            }
349	        }
350	    } else if let Some(short) = arg.to_short() {
351	        if !short.is_negative_number() {
352	            // Find the first takes_values option.
353	            let (leading_flags, takes_value_opt, mut short, _) = parse_shortflags(cmd, short);
354	
355	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
356	            if let Some(opt) = takes_value_opt {
357	                if !disabled.contains(opt.get_id()) {
358	                    let mut peek_short = short.clone();
359	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
360	                        short.next_flag();
361	                        true
362	                    } else {
363	                        false
364	                    };
365	
366	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
367	                    completions.extend(
368	                        complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
369	                            .into_iter()
370	                            .map(|comp| {
371	                                let sep = if has_equal { "=" } else { "" };
372	                                comp.add_prefix(format!("-{leading_flags}{sep}"))
373	                            }),
374	                    );
375	                }
376	            } else {
377	                completions.extend(
378	                    shorts_and_visible_aliases(cmd, disabled)
379	                        .into_iter()
380	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
381	                );
382	            }
383	        }
384	    }
385	    debug!("complete_option: completions={completions:?}");
386	    completions
387	}
