389	fn complete_arg_value(
390	    value: Result<&str, &OsStr>,
391	    arg: &clap::Arg,
392	    current_dir: Option<&std::path::Path>,
393	    arg_index: usize,
394	) -> Vec<CompletionCandidate> {
395	    let mut values = Vec::new();
396	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
397	
398	    let (prefix, value) =
399	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
400	
401	    let value_os = match value {
402	        Ok(value) => OsStr::new(value),
403	        Err(value_os) => value_os,
404	    };
405	
406	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
407	        values.extend(completer.complete_at(arg_index, value_os));
408	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
409	        values.extend(complete_value_candidates(
410	            value_os,
411	            completer.value_candidates(),
412	        ));
413	    } else if let Some(possible_values) = possible_values(arg) {
414	        if let Ok(value) = value {
415	            values.extend(complete_candidates_str(
416	                value,
417	                possible_value_candidates(possible_values),
418	            ));
419	        }
420	    } else {
421	        match arg.get_value_hint() {
422	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
423	                // Should not complete
424	            }
425	            clap::ValueHint::AnyPath => {
426	                values.extend(complete_path(value_os, current_dir, &|_| true));
427	            }
428	            clap::ValueHint::FilePath => {
429	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
430	            }
431	            clap::ValueHint::DirPath => {
432	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
433	            }
434	            clap::ValueHint::ExecutablePath => {
435	                use is_executable::IsExecutable;
436	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
437	            }
438	            clap::ValueHint::CommandName
439	            | clap::ValueHint::CommandString
440	            | clap::ValueHint::CommandWithArguments
441	            | clap::ValueHint::Username
442	            | clap::ValueHint::Hostname
443	            | clap::ValueHint::Url
444	            | clap::ValueHint::EmailAddress => {
445	                // No completion implementation
446	            }
447	            _ => {
448	                // Safe-ish fallback
449	                values.extend(complete_path(value_os, current_dir, &|_| true));
450	            }
451	        }
452	
453	        values.sort();
454	    }
455	
456	    if let Some(prefix) = prefix {
457	        values = values
458	            .into_iter()
459	            .map(|comp| comp.add_prefix(prefix))
460	            .collect();
461	    }
462	    values = values
463	        .into_iter()
464	        .map(|comp| {
465	            if comp.get_tag().is_some() {
466	                comp
467	            } else {
468	                comp.tag(Some(arg.to_string().into()))
469	            }
470	        })
471	        .collect();
472	
473	    debug!("complete_arg_value: values={values:?}");
474	    values
475	}
476	
477	fn rsplit_delimiter<'s, 'o>(
478	    value: Result<&'s str, &'o OsStr>,
479	    delimiter: Option<char>,
480	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
481	    let delimiter = delimiter?;
482	    let value = value.ok()?;
483	    let pos = value.rfind(delimiter)?;
484	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
485	    Some((Some(prefix), Ok(value)))
486	}
