488	fn complete_value_candidates(
489	    value: &OsStr,
490	    completer: &dyn ValueCandidates,
491	) -> Vec<CompletionCandidate> {
492	    debug!("complete_value_candidates: value={value:?}");
493	
494	    let mut values = completer.candidates();
495	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
496	    values
497	}
