499	fn complete_candidates_str(
500	    value: &str,
501	    mut values: Vec<CompletionCandidate>,
502	) -> Vec<CompletionCandidate> {
503	    debug!("complete_candidates_str: value={value:?}");
504	
505	    values.retain(|comp| comp.get_value().starts_with(value));
506	    values
507	}
