509	fn complete_value_candidates_str(
510	    value: &str,
511	    completer: &dyn ValueCandidates,
512	) -> Vec<CompletionCandidate> {
513	    debug!("complete_value_candidates_str: value={value:?}");
514	
515	    complete_candidates_str(value, completer.candidates())
516	}
