518	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
519	    debug!(
520	        "complete_subcommand: cmd={:?}, value={:?}",
521	        cmd.get_name(),
522	        value
523	    );
524	
525	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
526	        .into_iter()
527	        .filter(|x| x.get_value().starts_with(value))
528	        .collect();
529	    if cmd.is_allow_external_subcommands_set() {
530	        let external_completer = cmd.get::<SubcommandCandidates>();
531	        if let Some(completer) = external_completer {
532	            scs.extend(complete_value_candidates_str(
533	                value,
534	                completer.value_candidates(),
535	            ));
536	        }
537	    }
538	
539	    scs.sort();
540	    scs.dedup();
541	    scs
542	}
