544	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
545	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
546	fn longs_and_visible_aliases(
547	    p: &clap::Command,
548	    disabled: &HashSet<Id>,
549	) -> Vec<CompletionCandidate> {
550	    debug!("longs: name={}", p.get_name());
551	
552	    p.get_arguments()
553	        .filter(|a| !disabled.contains(a.get_id()))
554	        .filter_map(|a| {
555	            a.get_long_and_visible_aliases().map(|longs| {
556	                longs
557	                    .into_iter()
558	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
559	            })
560	        })
561	        .flatten()
562	        .collect()
563	}
564	
565	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
566	fn hidden_longs_aliases(p: &clap::Command, disabled: &HashSet<Id>) -> Vec<CompletionCandidate> {
567	    debug!("longs: name={}", p.get_name());
568	
569	    p.get_arguments()
570	        .filter(|a| !disabled.contains(a.get_id()))
571	        .filter_map(|a| {
572	            a.get_aliases().map(|longs| {
573	                longs.into_iter().map(|s| {
574	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
575	                })
576	            })
577	        })
578	        .flatten()
579	        .collect()
580	}
