582	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
583	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
584	fn shorts_and_visible_aliases(
585	    p: &clap::Command,
586	    disabled: &HashSet<Id>,
587	) -> Vec<CompletionCandidate> {
588	    debug!("shorts: name={}", p.get_name());
589	
590	    p.get_arguments()
591	        .filter(|a| !disabled.contains(a.get_id()))
592	        .filter_map(|a| {
593	            a.get_short_and_visible_aliases().map(|shorts| {
594	                shorts.into_iter().map(|s| {
595	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
596	                        a.get_help()
597	                            .cloned()
598	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
599	                    )
600	                })
601	            })
602	        })
603	        .flatten()
604	        .collect()
605	}
606	
607	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
608	    candidate
609	        .help(arg.get_help().cloned())
610	        .id(Some(format!("arg::{}", arg.get_id())))
611	        .tag(Some(
612	            arg.get_help_heading()
613	                .unwrap_or("Options")
614	                .to_owned()
615	                .into(),
616	        ))
617	        .display_order(Some(arg.get_display_order()))
618	        .hide(arg.is_hide_set())
619	}
620	
621	/// Get the possible values for completion
622	fn possible_values(
623	    a: &clap::Arg,
624	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
625	    if !a.get_num_args().expect("built").takes_values() {
626	        None
627	    } else {
628	        a.get_value_parser().possible_values()
629	    }
630	}
631	
632	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
633	///
634	/// Subcommand `rustup toolchain install` would be converted to
635	/// `("install", "rustup toolchain install")`.
636	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
637	    debug!("subcommands: name={}", p.get_name());
638	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
639	    p.get_subcommands()
640	        .flat_map(|sc| {
641	            sc.get_name_and_visible_aliases()
642	                .into_iter()
643	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
644	                .chain(sc.get_aliases().map(|s| {
645	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
646	                        .hide(true)
647	                }))
648	        })
649	        .collect()
650	}
651	
652	fn populate_command_candidate(
653	    candidate: CompletionCandidate,
654	    cmd: &clap::Command,
655	    subcommand: &clap::Command,
656	) -> CompletionCandidate {
657	    candidate
658	        .help(subcommand.get_about().cloned())
659	        .id(Some(format!("command::{}", subcommand.get_name())))
660	        .tag(Some(
661	            cmd.get_subcommand_help_heading()
662	                .unwrap_or("Commands")
663	                .to_owned()
664	                .into(),
665	        ))
666	        .display_order(Some(subcommand.get_display_order()))
667	        .hide(subcommand.is_hide_set())
668	}
669	
670	/// Parse the short flags and find the first `takes_values` option.
671	///
672	/// The returned bool is `true` only when every scanned cluster member was a
673	/// recognized option. Anything after the first value-taking option is the
674	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
675	/// characters make the result `false`.
676	fn parse_shortflags<'c, 's>(
677	    cmd: &'c clap::Command,
678	    mut short: clap_lex::ShortFlags<'s>,
679	) -> (
680	    String,
681	    Option<&'c clap::Arg>,
682	    clap_lex::ShortFlags<'s>,
683	    bool,
684	) {
685	    let takes_value_opt;
686	    let mut leading_flags = String::new();
687	    let mut cluster_valid = true;
688	    // Find the first takes_values option.
689	    loop {
690	        match short.next_flag() {
691	            Some(Ok(opt)) => {
692	                leading_flags.push(opt);
693	                let found = cmd.get_arguments().find(|a| {
694	                    let shorts = a.get_short_and_visible_aliases();
695	                    let is_find = shorts.map(|v| {
696	                        let mut iter = v.into_iter();
697	                        let c = iter.find(|c| *c == opt);
698	                        c.is_some()
699	                    });
700	                    is_find.unwrap_or(false)
701	                });
702	                if let Some(opt) = found {
703	                    if opt.get_num_args().expect("built").takes_values() {
704	                        takes_value_opt = Some(opt);
705	                        break;
706	                    }
707	                } else {
708	                    cluster_valid = false;
709	                }
710	            }
711	            Some(Err(_)) => {
712	                cluster_valid = false;
713	                takes_value_opt = None;
714	                break;
715	            }
716	            None => {
717	                takes_value_opt = None;
718	                break;
719	            }
720	        }
721	    }
722	
723	    (leading_flags, takes_value_opt, short, cluster_valid)
724	}
725	
726	/// Parse the positional arguments. Return the new state and the new positional index.
727	fn parse_positional<'a>(
728	    cmd: &clap::Command,
729	    pos_index: usize,
730	    is_escaped: bool,
731	    state: ParseState<'a>,
732	) -> (ParseState<'a>, usize) {
733	    let pos_arg = cmd
734	        .get_positionals()
735	        .find(|p| p.get_index() == Some(pos_index));
736	    let num_args = pos_arg
737	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
738	        .unwrap_or(1);
739	
740	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
741	        if num_args > 1 {
742	            (ParseState::Pos((pos_index, 1)), pos_index)
743	        } else {
744	            if is_escaped {
745	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
746	            } else {
747	                (ParseState::ValueDone, pos_index + 1)
748	            }
749	        }
750	    };
751	    match state {
752	        ParseState::ValueDone => {
753	            update_state_with_new_positional(pos_index)
754	        },
755	        ParseState::Pos((prev_pos_index, num_arg)) => {
756	            if prev_pos_index == pos_index {
757	                if num_arg + 1 < num_args {
758	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
759	                } else {
760	                    if is_escaped {
761	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
762	                    } else {
763	                        (ParseState::ValueDone, pos_index + 1)
764	                    }
765	                }
766	            } else {
767	                update_state_with_new_positional(pos_index)
768	            }
769	        }
770	        ParseState::Opt(..) => unreachable!(
771	            "This branch won't be hit,
772	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
773	        ),
774	    }
775	}
776	
777	/// Parse optional flag argument. Return new state
778	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
779	    let range = opt.get_num_args().expect("built");
780	    let max = range.max_values();
781	    if count < max {
782	        ParseState::Opt((opt, count + 1))
783	    } else {
784	        ParseState::ValueDone
785	    }
786	}
787	
788	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
789	    cmd.get_positionals()
790	        .find(|a| a.get_index() == Some(pos_index))
791	        .map(|p| p.is_allow_hyphen_values_set())
792	        .unwrap_or(false)
793	}
794	
795	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
796	    let val = arg.to_value_os();
797	    if val.starts_with("-") {
798	        if let ParseState::Opt((opt, _)) = state {
799	            return opt.is_allow_hyphen_values_set();
800	        }
801	    }
802	
803	    false
804	}
805	
806	/// Arguments that must not be offered because they conflict with an explicitly
807	/// present option. The present options themselves are never disabled.
808	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
809	    let mut disabled = HashSet::new();
810	    if explicit.is_empty() {
811	        return disabled;
812	    }
813	    for arg in cmd.get_arguments() {
814	        if explicit.contains(arg.get_id()) {
815	            // A present option hides everything it conflicts with ...
816	            for id in arg_direct_conflicts(cmd, arg) {
817	                if !explicit.contains(&id) {
818	                    disabled.insert(id);
819	                }
820	            }
821	        } else {
822	            // ... and is hidden when either side declares the conflict.
823	            if arg_direct_conflicts(cmd, arg)
824	                .iter()
825	                .any(|id| explicit.contains(id))
826	            {
827	                disabled.insert(arg.get_id().clone());
828	            }
829	        }
830	    }
831	    disabled
832	}
833	
834	/// Conflict partners of `arg`, following the same rules as clap's parser:
835	/// - the argument's own `conflicts_with` / `conflicts_with_all`
836	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
837	/// - the other members of non-`multiple` groups
838	///
839	/// Group ids are expanded to their argument members.
840	/// `overrides_with` relationships are intentionally not considered.
841	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
842	    let mut conflicts = arg
843	        .get_conflicts_with()
844	        .map(ToOwned::to_owned)
845	        .collect::<HashSet<_>>();
846	    for group in cmd.get_groups() {
847	        let members = unroll_group(cmd, group.get_id());
848	        if !members.iter().any(|m| m == arg.get_id()) {
849	            continue;
850	        }
851	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
852	        if !group.is_multiple_set() {
853	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
854	        }
855	    }
856	    conflicts
857	        .iter()
858	        .flat_map(|id| unroll_group(cmd, id))
859	        .collect()
860	}
861	
862	/// Resolve an argument or group id to its argument members.
863	/// Unknown ids resolve to themselves.
864	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
865	    let mut pending = vec![id.clone()];
866	    let mut args = Vec::new();
867	    while let Some(id) = pending.pop() {
868	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
869	            if !args.contains(&id) {
870	                args.push(id);
871	            }
872	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
873	            pending.extend(group.get_args().map(ToOwned::to_owned));
874	        } else if !args.contains(&id) {
875	            args.push(id);
876	        }
877	    }
878	    args
879	}
