105	                    };
106	                } else if pos_allows_hyphen(current_cmd, pos_index) {
107	                    (next_state, pos_index) =
108	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
109	                }
110	            }
111	        } else if let Some(short) = arg.to_short() {
112	            let (leading_flags, takes_value_opt, mut short, cluster_valid) =
113	                parse_shortflags(current_cmd, short);
114	            // Only a cluster made entirely of recognized flags records state.
115	            // Splitting an invalid short string into known and unknown members
116	            // would be guesswork and could suppress conflicting candidates, so
117	            // invalid clusters keep the existing completion behavior; clap's
